"""conda-lock.yml, pixi.lock and pixi.toml (fixtures in the formats the tools write)."""

import subprocess

import pytest

from depshift import conda
from depshift.deps import discover_dependencies
from depshift.lockfiles import locked_versions
from depshift.review import changed_dependencies, is_dep_file

