PIXI_TOML = """\
[workspace]
name = "demo"
channels = ["conda-forge"]
platforms = ["linux-64"]

[dependencies]
python = "3.12.*"
numpy = ">=2.0,<3"
python-build = "*"
rust = ">=1.80"
pandas = "2.1.*"
scipy = "=1.11"

[pypi-dependencies]
flask = "==2.2.5"
myproject = { path = ".", editable = true }
requests = { version = ">=2.31" }

[feature.test.dependencies]
pytest = ">=8"

[target.linux-64.dependencies]
pytorch = "2.2.1"
"""


def test_yaml_items_reads_scalars_and_nested_entries():
    (a, b) = conda.yaml_items("other: 1\npackages:\n- name: a\n  depends:\n  - python >=3\n  x: '1'\n"
                              "- name: b\n  dependencies:\n    libz: '>=1'\nafter: 2\n", "packages")
    assert a["name"] == "a" and a["x"] == "1" and a["_children"]["depends"] == ["python >=3"]
    assert b["_children"]["dependencies"] == ["libz: '>=1'"]


def test_conda_lock(tmp_path):
    (tmp_path / "conda-lock.yml").write_text(CONDA_LOCK)
    locks = locked_versions(str(tmp_path))
    assert {n: p.version for n, p in locks.items()} == {
        "numpy": "1.26.4", "torch": "2.2.1", "requests": "2.31.0"}  # no openssl, no python
    assert locks["numpy"].source == "conda-lock.yml"


def test_conda_lock_prefers_this_platform(tmp_path, monkeypatch):
    lock = CONDA_LOCK.replace("  version: 1.26.4\n  manager: conda\n  platform: osx-arm64",
                              "  version: 1.26.3\n  manager: conda\n  platform: osx-arm64")
    (tmp_path / "conda-lock.yml").write_text(lock)
    monkeypatch.setattr(conda, "current_platform", lambda: "osx-arm64")
    assert locked_versions(str(tmp_path))["numpy"].version == "1.26.3"
    monkeypatch.setattr(conda, "current_platform", lambda: "linux-64")
    assert locked_versions(str(tmp_path))["numpy"].version == "1.26.4"


def test_pixi_lock(tmp_path):
    (tmp_path / "pixi.lock").write_text(PIXI_LOCK)
    assert {n: p.version for n, p in locked_versions(str(tmp_path)).items()} == {
        "numpy": "2.1.0",        # name and version from the archive URL
        "build": "1.2.2",        # PyPI name from purls, not the conda name python-build
        "flask": "2.2.5",        # a PyPI entry
        "pandas": "2.1.4",       # the older format, with name/version keys
    }  # no _openmp_mutex or rust (purls: []), no cpython, not the project itself


def test_highest_version_when_environments_differ(tmp_path):
    extra = ("- pypi: https://files.pythonhosted.org/packages/flask-3.0.0-py3-none-any.whl\n"
             "  name: flask\n  version: 3.0.0\n")
    (tmp_path / "pixi.lock").write_text(PIXI_LOCK + extra)
    assert locked_versions(str(tmp_path))["flask"].version == "3.0.0"


def test_pixi_toml_with_lock_names(tmp_path):
    (tmp_path / "pixi.toml").write_text(PIXI_TOML)
    (tmp_path / "pixi.lock").write_text(PIXI_LOCK)
    deps = {d.name: d for d in discover_dependencies(str(tmp_path))}
    # rust dropped (the lock says it isn't a Python package), python-build is build
    assert set(deps) == {"numpy", "build", "pandas", "scipy", "flask", "requests", "pytest", "torch"}
    assert deps["flask"].pinned_version == "2.2.5"
    assert deps["torch"].pinned_version == "2.2.1"   # a bare conda version is exact
    assert deps["pandas"].raw == "pandas==2.1.*"
    assert deps["scipy"].raw == "scipy==1.11.*"     # conda "=1.11" is 1.11.*
    assert deps["requests"].raw == "requests>=2.31"


def test_pixi_toml_without_lock_guesses_names(tmp_path):
    (tmp_path / "pixi.toml").write_text(PIXI_TOML)
    names = {d.name for d in discover_dependencies(str(tmp_path))}
    assert "build" in names and "torch" in names and "python" not in names


def test_pixi_toml_tomllib_cannot_parse(tmp_path):
    # TOML 1.1: an inline table over several lines, which pixi accepts
    text = PIXI_TOML + '\n[feature.docs.pypi-dependencies]\nmkdocs = { version = ">=1.5",\n  extras = ["x"] }\n'
    (tmp_path / "pixi.toml").write_text(text)
    (tmp_path / "pixi.lock").write_text(PIXI_LOCK)
    names = {d.name for d in discover_dependencies(str(tmp_path))}
    assert {"numpy", "flask", "requests", "pytest", "mkdocs"} <= names and "rust" not in names


def test_pyproject_tool_pixi(tmp_path):
    (tmp_path / "pyproject.toml").write_text(
        '[project]\nname = "x"\nversion = "0"\ndependencies = ["click>=8"]\n'
        '[tool.pixi.dependencies]\nnumpy = ">=2"\n[tool.pixi.pypi-dependencies]\nhttpx = "*"\n')
    assert {d.name for d in discover_dependencies(str(tmp_path))} == {"click", "numpy", "httpx"}


def test_environment_yml_conda_names(tmp_path):
    (tmp_path / "environment.yml").write_text(
        "name: x\ndependencies:\n  - python=3.11\n  - pytorch=2.2.1\n  - matplotlib-base\n")
    assert {d.name for d in discover_dependencies(str(tmp_path))} == {"torch", "matplotlib"}


@pytest.mark.parametrize("path", ["conda-lock.yml", "conda-lock.yaml", "pixi.lock", "pixi.toml"])
def test_conda_files_are_watched_and_reviewed(path):
    assert is_dep_file(path)


def test_review_sees_a_pixi_lock_change(tmp_path):
    def git(*a):
        subprocess.run(["git", "-C", str(tmp_path), *a], check=True, capture_output=True)
    git("init", "-q", "-b", "main")
    git("config", "user.email", "t@example.com")
    git("config", "user.name", "t")
    (tmp_path / "pixi.toml").write_text(PIXI_TOML)
    (tmp_path / "pixi.lock").write_text(PIXI_LOCK)
    git("add", "-A")
    git("commit", "-q", "-m", "base")
    (tmp_path / "pixi.lock").write_text(PIXI_LOCK.replace("numpy-2.1.0-", "numpy-2.1.3-"))
    assert [(c.name, c.old, c.new) for c in changed_dependencies(str(tmp_path), "HEAD")] == \
        [("numpy", "2.1.0", "2.1.3")]
